export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export function checkAABB(a: Rect, b: Rect): boolean {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

export function drawSpriteFrame(
  ctx: CanvasRenderingContext2D,
  image: CanvasImageSource,
  frameIndex: number,
  frameWidth: number,
  frameHeight: number,
  destX: number,
  destY: number,
  cols: number
): void {
  const sx = (frameIndex % cols) * frameWidth;
  const sy = Math.floor(frameIndex / cols) * frameHeight;
  ctx.drawImage(image, sx, sy, frameWidth, frameHeight, destX, destY, frameWidth, frameHeight);
}

